-- ============================================================
-- Knowledge-check quizzes for "qa-leadership-academy".
-- Generated by scripts/content/build-quizzes.mjs — do not hand-edit;
-- edit scripts/content/qa-leadership-quizzes-b.mjs and regenerate. Run AFTER the course,
-- modules and schema exist. Idempotent: a module that already has a quiz
-- is skipped (no quizzes or attempts are ever deleted).
-- ============================================================

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 7),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Northstar's fortnightly report shows test cases and bugs found at record highs, yet production incidents rose over the same period. The CTO asks whether QA is doing well or badly. What is the strongest response?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Neither count answers the question — both rise for good and bad reasons; point to the rising escaped-defect trend as the signal that carries a decision and propose replacing the counts$qz$, true), ($qz$QA is performing well: the team found more defects and wrote more cases than ever, so the incidents reflect development quality, not testing$qz$, false), ($qz$QA is performing badly: rising incidents alongside high bug counts prove the testing missed too much and coverage must increase$qz$, false), ($qz$Reserve judgement until the pass rate is available, since that is the metric that best grades whether the release was healthy$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A QA manager reports that pipeline feedback time and early QA involvement both improved sharply, and concludes quality has improved. A month later a serious incident occurs. What does this reveal?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Leading signals only predict outcomes and must be paired with and validated against lagging outcomes — either the improvement was superficial or the assumed causal link does not hold here$qz$, true), ($qz$The leading indicators were simply measured incorrectly and need a more precise definition before they can be trusted again$qz$, false), ($qz$The incident was bad luck; the leading signals were green, so the quality conclusion was sound and should stand$qz$, false), ($qz$Leading indicators are inherently useless for QA and the manager should report only escaped defects and incidents in future$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$To show quality is improving, a manager proposes a target of driving escaped defects to zero next quarter. Why is this the wrong target?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$A zero target invites reclassifying escapes as non-production or over-testing that destroys delivery speed; track escape rate as an explainable trend by origin and severity, at a consciously accepted level$qz$, true), ($qz$Zero is unreachable, so a softer numeric target such as halving escapes is the correct scorecard to commit the team to instead$qz$, false), ($qz$Escaped defects are a lagging metric and should never be tracked; only leading indicators belong on a target$qz$, false), ($qz$The target is fine in principle but should be owned by development, since they create the defects that escape$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The CTO cites Northstar's large Selenium suite as evidence of strong coverage and asks for more automated tests. The suite is slow and heavily flaky. What is the strongest reframe?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Shift the measure from size to trust and fit — track flaky-test rate, pipeline feedback time and risk coverage, and warn that success will likely mean the test count falls$qz$, false), ($qz$Agree to add the tests but insist on a proportional increase in headcount to maintain the larger suite$qz$, false), ($qz$Report the suite's pass rate to reassure the CTO that the existing tests are protecting the product well$qz$, false), ($qz$The count hides flakiness, run time and maintenance cost; measure flaky rate, feedback time and risk coverage of top-band risks, and accept the test count may fall as success$qz$, true)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$After introducing heavier pre-release gates, a manager reports that change failure rate dropped sharply and presents it as a clear quality win. What should a delivery-literate leader want to see first?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$The throughput metrics alongside it — a lower change failure rate bought by slowing releases and shipping less is a trade of speed for stability, not a win$qz$, true), ($qz$Confirmation that the gates were manual, since automated gates would make the improvement less trustworthy$qz$, false), ($qz$The absolute number of defects the gates caught, to quantify the return on the extra process$qz$, false), ($qz$Nothing further — a falling change failure rate is unambiguous and should be accepted as a quality improvement$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You are designing separate dashboards for the QA team, engineering leadership and the executive board. What best reflects sound audience-specific design?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Publish one comprehensive dashboard to everyone so all stakeholders see the same numbers and nobody can accuse QA of hiding data$qz$, false), ($qz$Give the executive board the internal plumbing — flaky rate and feedback time — so they can judge the health of the suite directly$qz$, false), ($qz$Give each audience the decision-linked view it acts on — the executive sees outcomes like escaped defects and change failure rate, not the flaky rate and feedback time the QA team needs$qz$, true), ($qz$Give the executive board test-case and bug counts, since those are the simplest figures for non-technical leaders to follow$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 8),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The CTO asks you to add a thousand more automated tests this year on top of a large, slow, flaky UI suite. Why is agreeing to the number the wrong first move?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$A test-count target is a solution with no stated problem and would multiply the existing maintenance and trust liabilities; surface the outcomes wanted and design a strategy, which almost certainly is not more UI tests$qz$, true), ($qz$The number is too low to matter; you should counter with a more ambitious coverage target to signal real commitment$qz$, false), ($qz$The existing suite proves the tool is wrong, so the right first move is to propose migrating to a better framework before adding tests$qz$, false), ($qz$Adding tests is always correct, but only after the team has been expanded to maintain them$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The Payments squad wants the whole checkout journey automated as UI end-to-end tests because "that is what the customer does". What is the sounder approach?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Automate every journey through the UI as requested, since only end-to-end tests reproduce the real customer experience$qz$, false), ($qz$Decline checkout automation entirely because UI tests are brittle, and rely on exploratory testing for the whole flow$qz$, false), ($qz$Decompose the risk — push calculations and rules to dev-owned unit tests and the provider boundary to contract tests, and keep only a couple of end-to-end UI checks to prove it hangs together$qz$, true), ($qz$Automate the full journey now but at the API layer only, replacing every UI interaction with a direct service call$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A senior stakeholder insists you fully automate a new onboarding flow that the growth team redesigns almost every sprint and whose quality is largely about how intuitive it feels. Why is full UI automation the wrong call?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$The flow is unstable, so automation means constant rewrites, and its real quality is experiential — a human judgement; automate only the stable factual guarantees underneath at API level and keep exploratory eyes on the experience$qz$, true), ($qz$Onboarding is low-risk, so it does not warrant any automated coverage and should be left to manual spot-checks$qz$, false), ($qz$Full automation is correct; the churn simply requires a dedicated engineer to keep the UI tests updated each sprint$qz$, false), ($qz$The problem is the tool — a self-healing UI framework would make automating the changing flow entirely worthwhile$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Northstar's suite is heavily UI-weighted, slow and flaky while unit and API coverage is patchy. A stakeholder suggests fixing it by migrating to a faster UI tool. Why will that not solve the core problem?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$The problem is the distribution — too much testing at the slowest, most brittle level — so a faster UI runner still leaves a fragile suite; shift coverage down to unit, contract and API level incrementally, not as a big-bang rewrite$qz$, true), ($qz$The tool is genuinely the constraint, so the migration will fix it provided the whole suite is ported in one release$qz$, false), ($qz$A faster UI tool will halve the run time, which is the real problem, so the migration is the right first step$qz$, false), ($qz$The suite should simply be deleted in full and rebuilt from scratch at the UI level in the new tool$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Dan wants to migrate the flaky, QA-owned UI suite to a newer, more fashionable framework. What single question should you ask before approving?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Whether the new framework has better community support and documentation than the current one$qz$, false), ($qz$How long the migration will take and whether it can be squeezed into the current quarter$qz$, false), ($qz$"If we migrate but keep the same distribution, ownership and strategy, what actually gets better?" — if the honest answer is "little", the framework is masking a strategy and ownership problem$qz$, true), ($qz$Whether Dan has the certification needed to lead adoption of the new tool$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Northstar's automation is owned entirely by QA; the developers who break the tests feel no responsibility for them. What does this most reveal about the automation strategy?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$A distribution problem is usually an ownership problem in disguise — push coverage to levels developers will co-own and choose tooling in their language, or the suite will keep orphaning$qz$, true), ($qz$QA ownership is correct and should be reinforced, since a single owner keeps the suite coherent and consistent$qz$, false), ($qz$The fix is to hire more QA automation engineers so the existing owner is less overloaded$qz$, false), ($qz$Ownership is a cultural nicety; as long as the tests pass in the pipeline, who maintains them does not affect strategy$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 9),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The CTO asks you to "roll out AI across testing to speed us up", while two testers are already quietly pasting code into a public tool. What is the strongest first move?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Map concrete use cases by value and risk first, then enable the high-value/low-risk ones, control the risky ones, and stop the unsafe one while offering a safe alternative so it does not go underground$qz$, true), ($qz$Ban all AI use immediately until a formal policy is written, to remove the data-leak risk at once$qz$, false), ($qz$Roll AI out broadly this quarter as instructed and report back on the speed gains it delivers$qz$, false), ($qz$Buy the enterprise licence the CTO wants and let each tester find the use cases that suit their own work$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A tester proudly shows you an entire automated suite an AI generated overnight — dozens of passing tests. How should you respond?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Merge them quickly to capture the productivity gain, since they compile and pass, then review a sample if time later permits$qz$, false), ($qz$Encourage the initiative but do not trust the green — verify the tests actually fail when the behaviour breaks and check what they truly assert before any enter the suite$qz$, true), ($qz$Reject AI-generated tests on principle, because automation must be hand-written to be trustworthy$qz$, false), ($qz$Accept them as coverage and reduce the manual regression accordingly, since the count has risen sharply$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An AI tool analyses a cluster of failures and produces a confident, well-written root-cause explanation. A team lead wants to send it straight to the VP of Engineering as the finding. Why should you pause?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$AI infers causation from surface patterns and can be fluently, confidently wrong; hand the hypothesis to an engineer to verify against the real system, and report only the verified cause, owned by a human$qz$, true), ($qz$The VP should hear the hypothesis first so she can allocate engineers to investigate it before anyone verifies it$qz$, false), ($qz$AI summaries are always unreliable, so the analysis should be discarded and the investigation restarted manually$qz$, false), ($qz$The concern is only formatting — the explanation should be rewritten in the team's house style before it goes up$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You discover testers routinely paste production source code and customer-bearing tickets into a free public AI chatbot, with no policy in place. What is the leadership response?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Treat it as a live governance and data-protection risk — provide a governed tool and a safe alternative rather than only banning it, so the genuine value is captured under controls that match the risk$qz$, true), ($qz$Leave it alone, since no one has formally approved it and therefore the organisation carries no responsibility for it$qz$, false), ($qz$Issue an outright ban and consider the matter closed, since removing the tool removes the risk$qz$, false), ($qz$Encourage wider use because it is clearly speeding the team up, and revisit governance only if a leak occurs$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A severity call driven partly by an AI defect summary later turns out to be wrong and causes real customer impact. How should accountability be understood?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$A human owns the severity and release decisions and their consequences; "the AI classified it as low severity" is never an acceptable account — AI assists the judgement, it does not make it$qz$, true), ($qz$The tool vendor bears responsibility, since its model produced the classification the team relied upon$qz$, false), ($qz$No one is accountable, because the decision was informed by an automated system acting in good faith$qz$, false), ($qz$Accountability sits with whoever configured the AI tool, not with the engineer who acted on its output$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A tester presents an AI-generated set of forty test cases as evidence that a feature is "thoroughly covered". Why be cautious?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$A long, fluent list creates false completeness but reflects no knowledge of the system's real risks, architecture or incident history; treat it as a divergent starting point and check the context-specific, high-risk scenarios are covered and the expected results verified$qz$, true), ($qz$Forty cases is too few for thorough coverage; the tester should ask the AI to generate several hundred more before signing off$qz$, false), ($qz$AI-generated cases are always wrong and should be deleted, with the tester designing every case unaided instead$qz$, false), ($qz$The concern is efficiency — running forty AI-written cases will slow the suite, so the list should be trimmed to save time$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 10),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Product insists on a Friday release; testing is incomplete on a payments-adjacent path with a real financial risk. Your instinct is to refuse: "We can't ship, it's not signed off." Why is this the weaker move?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$It claims an authority QA does not hold, conveys no actionable information and no path, and invites being overruled; instead present tested, untested, known defects, residual risk in business terms, mitigations and a recommendation, then let the accountable owner decide$qz$, true), ($qz$It is the correct move — QA sign-off is a hard gate and the release cannot proceed without it under any circumstances$qz$, false), ($qz$It is too soft; QA should escalate straight to the CTO to have the deadline formally overruled$qz$, false), ($qz$It is fine as long as QA also privately agrees to ship, so the relationship with product is preserved$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You recommend a phased launch, but the CTO — the accountable owner — overrules you and says "ship it all Friday", accepting the reconciliation risk you flagged. What do you do next?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Accept the decision without sulking, make the risk acceptance explicit and on the record, add monitoring on the exposed area and ready a fast-follow fix$qz$, true), ($qz$Refuse to support the release and withhold QA involvement so the risk sits clearly with the CTO$qz$, false), ($qz$Cave silently, say nothing further, and hope the risk does not materialise$qz$, false), ($qz$Re-litigate the decision in the release channel so the whole team knows you disagreed$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You want funding for a new test-data capability. You send the same detailed technical proposal to your testers, the VP of Engineering and the CFO. Why is this likely to fail?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Each audience is measured on different things and acts on different information; translate the one case into engineering-health terms for the VP, cost-and-risk terms for the CFO and concrete day-to-day relief for the team, targeting the people who decide the budget$qz$, true), ($qz$The proposal is too short to be credible to executives and needs far more technical detail across the board$qz$, false), ($qz$Test-data work is an engineering concern, so only the VP should receive any proposal at all$qz$, false), ($qz$Sending one message to everyone is efficient and correct; the likely failure is simply that the idea is unfunded this year$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$The day before a launch, a product owner asks QA: "Is it ready to ship?" Testing is incomplete on two secondary paths. What is the strongest response?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$A crisp residual-risk picture — what is tested and solid, what is not and its realistic worst case, a mitigation and a recommendation — leaving the accountable owner to make the go/no-go call$qz$, true), ($qz$A plain "no", because incomplete testing means the feature cannot responsibly be called ready$qz$, false), ($qz$A plain "yes", to protect the relationship and avoid being seen as the blocker on launch day$qz$, false), ($qz$A summary of testing status — cases run and remaining — so product can judge readiness from the numbers$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A developer wants a defect's severity downgraded so it does not block release; you believe it is serious. Insisting on the label starts a standoff. What is the more effective approach?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Stop arguing the label and reframe to real-world impact and likelihood — what happens to a customer if it triggers and how often — so both sides reason about risk, and agree the action from there$qz$, true), ($qz$Hold firm on the high severity as a matter of principle, since conceding sets a precedent that severities can be negotiated$qz$, false), ($qz$Concede the downgrade to keep the peace, since a single defect is not worth damaging the relationship over$qz$, false), ($qz$Escalate the severity dispute to the VP so an authority settles the label definitively$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Marcus, the Payments lead, believes good developers do not need a QA team and is unconvinced rather than hostile. How do you best shift him?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Do not argue the abstract case for QA; demonstrate value on a real risk his unit and contract tests structurally cannot catch, framed as help — and accept that a neutral, respectful working relationship is a good outcome$qz$, true), ($qz$Build a data-backed presentation proving QA's value in general and take him through it until he concedes the point$qz$, false), ($qz$Escalate to Priya to have QA involvement in Payments mandated over his objection$qz$, false), ($qz$Leave Payments alone, since a sceptical lead means QA effort there will always be wasted$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 11),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$It is a release afternoon and a payment-path defect has just surfaced. Sofia — fully capable — asks "how do you want me to approach this?" Your coaching instinct says to hand it back with a question. What should you actually do?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Manage now, coach later — give clear direction under the time pressure, and revisit how she would structure her own approach in a calmer 1:1 afterwards$qz$, true), ($qz$Hand it back with an open question, since coaching capable people builds the judgement you want them to own$qz$, false), ($qz$Take over and fix it yourself, since a live payment defect is too important to delegate$qz$, false), ($qz$Tell her to follow whatever process feels right, to avoid undermining her autonomy mid-incident$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A senior tester keeps bringing you decisions they are perfectly capable of making, asking you to choose. Deciding is quick and your calls are sound. What is the risk, and what should you do?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Deciding for them is fast today but trains dependency and caps them at your judgement; shift to coaching — hand the decision back with a question — and reserve directing for genuinely high-risk or non-negotiable matters$qz$, true), ($qz$Keep deciding, since your judgement is sound and it resolves the questions fastest for the team$qz$, false), ($qz$Tell them to stop bringing you decisions, so they learn to be more independent$qz$, false), ($qz$Escalate their over-reliance as a performance concern, since a senior should not need this much input$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You need to tell a strong performer that their habit of rewriting colleagues' work "to fix it" is demoralising the team. You are irritated, having noticed it three times. How should you approach it?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Do not deliver it while irritated or as a one-off note — three times is a pattern, so plan a performance-style conversation on the observable behaviour and its impact, invite their side, and if it touches how others are treated, check whether it is a conduct matter needing HR$qz$, true), ($qz$Give immediate situation–behaviour–impact feedback in the moment you next see it happen, exactly as for a single incident$qz$, false), ($qz$Let it go, since the person is a strong performer and the rewrites do improve the work$qz$, false), ($qz$Raise it lightly at the next appraisal, batched with your other observations from the period$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You inherit a QA team with no skills matrix and no progression ladder, and you are frustrated that a long-serving tester has not grown their skills. Before raising it, what must you do?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Set the expectation explicitly and forward-looking first — define what "good" and progression mean for the role, name the gap against that standard, and agree it — because you cannot fairly hold someone to a standard that was never defined$qz$, true), ($qz$Raise the shortfall directly, since a long-serving tester should already know what "senior" requires$qz$, false), ($qz$Begin a formal performance process straight away, given how long the stagnation has persisted$qz$, false), ($qz$Reassign the tester to simpler work rather than have an awkward conversation about skills$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A feedback conversation with a team member is starting to look as though it could affect their job, pay or formal record. How should a QA leader handle this?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Involve HR early and follow the organisation's process and local employment law — a conversation framework is for fair, everyday feedback, not for running a disciplinary$qz$, true), ($qz$Keep handling it privately as coaching, since bringing in HR would escalate matters unnecessarily$qz$, false), ($qz$Apply the situation–behaviour–impact structure more firmly, since a good enough framework removes the need for formal process$qz$, false), ($qz$Delay any action until the next review cycle so HR involvement can be avoided altogether$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A junior tester is stuck on a kind of problem they have never faced and genuinely has no framework for it. Your instinct is to ask "what do you think you should do?" What is the better move?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Teach the skill first and coach its use second — show them how you would approach it once, then let them drive the next one; coaching someone who lacks the skill is abandonment with better manners$qz$, true), ($qz$Ask the open coaching question anyway, since discovering the answer themselves builds the strongest learning$qz$, false), ($qz$Reassign the task to someone experienced so the work is not held up$qz$, false), ($qz$Give them documentation to read and expect them to work it out independently by the deadline$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'qa-leadership-academy' and mo.module_number = 12),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You finish the diagnostic programme with a stack of strong artefacts and prepare to present all of them to the CTO, each arguing its own priority. Why is this a weak position?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Many competing documents read as activity rather than direction and hide the trade-offs; synthesise them into one narrative built on the few root causes the symptoms trace back to, reconcile the conflicts, and lead with a single statement of strategic intent$qz$, true), ($qz$The artefacts are too detailed for a CTO; each should be cut to a single page and then all presented together$qz$, false), ($qz$The position is strong — showing all the analysis demonstrates rigour and builds the CTO's confidence in QA$qz$, false), ($qz$The problem is ordering; present the artefacts in priority sequence and let the CTO choose which to fund$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Your prioritisation matrix ranks "rebuild the automation suite" as the single highest-impact improvement, so you plan to start it in month one. What is the risk in this reasoning?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$Highest priority is not the same as first in sequence — the rebuild likely depends on preconditions such as stable environments and the right skills, so map dependencies and sequence enabling, credibility-building work ahead of it$qz$, true), ($qz$There is no risk; the highest-impact item should always be started first to maximise the transformation's return$qz$, false), ($qz$The risk is only that the rebuild is expensive, so it should wait until a larger budget is secured$qz$, false), ($qz$Automation should never be the highest-impact item, so the matrix scoring must be discarded$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A leader correctly identifies that the real problems are structural and spends the first two quarters entirely on a large automation rebuild with nothing else visible. The sponsor grows sceptical and funding is questioned. What did the leader get wrong?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$They were right about the problems but neglected credibility and momentum — with no visible early wins the sponsor lost faith before the slow payoff arrived; lead with genuine quick wins and ship the rebuild in visible slices$qz$, true), ($qz$They chose the wrong structural change; the rebuild was never worth doing and should have been dropped$qz$, false), ($qz$They should have promised the sponsor a firm completion date for the rebuild to hold confidence$qz$, false), ($qz$Nothing — the sponsor simply lacked patience, and the leader should have pressed on unchanged$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A QA manager submits a business case asking for two more testers and a new automation tool "to improve coverage and reduce the bug backlog", citing a precise projected percentage improvement in quality. The board declines. What are the core weaknesses?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$It asks for inputs rather than outcomes in the currencies executives fund, and leans on an invented-looking precise figure that erodes trust; rebuild it around risk, delivery and cost with grounded ranges, honest uncertainty and a priced cost of inaction$qz$, true), ($qz$The request is too modest; a bolder ask for a larger team and toolset would have signalled the seriousness the board expects$qz$, false), ($qz$The percentage was too low to impress the board; a higher projected improvement would have won approval$qz$, false), ($qz$The case failed only because it went to the board rather than to the VP of Engineering, who owns QA budgets$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A new Head of QA writes a 90-day plan whose day-90 milestone is "automation suite fully rebuilt and stable, regression under one hour". Why is this risky even though the rebuild is the right structural change?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$A full estate rebuild is a multi-quarter change, so promising it in ninety days over-commits and will fail visibly; front-load quick wins, start the rebuild as foundation work, stand up the metric that will prove it, and end at a checkpoint with early evidence$qz$, true), ($qz$The milestone is fine; the risk is only that "under one hour" is too specific and should be left open$qz$, false), ($qz$Ninety days is the wrong horizon entirely; a first plan should never set concrete milestones$qz$, false), ($qz$The plan is sound as long as the whole team is dedicated to the rebuild and all other work is paused$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Your synthesised backlog has fourteen sensible improvements and the team is keen to start them all. What is the senior move?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Run few things concurrently and finish them, sized to what the team and organisation can absorb, and keep an explicit, reasoned "not now" list — starting everything at once exhausts people and delivers nothing$qz$, true), ($qz$Start all fourteen, since each is individually justified and delay only postpones the benefits$qz$, false), ($qz$Start whichever items the team is most enthusiastic about, to sustain morale during the change$qz$, false), ($qz$Quietly drop the weakest items without comment, so the backlog looks focused without a formal "not now" list$qz$, false)) as v(t, c) returning question_id)
select 1;

